-- B10 Golf: gemeinsame Datenbank in Supabase einrichten
-- 1. Unten GRUPPEN-CODE durch euren eigenen Code ersetzen (z. B. "Birdie-Wannsee-2026").
--    Nur wer diesen Code kennt, kann lesen und schreiben. Den Code NICHT ins Repository schreiben.
-- 2. In Supabase: SQL Editor → New query → alles einfügen → Run.

create table if not exists public.docs (
  collection text not null,
  id         text not null,
  data       jsonb not null,
  updated_at timestamptz not null default now(),
  primary key (collection, id)
);

alter table public.docs enable row level security;

-- Zugriff nur mit dem Gruppen-Code (die App schickt ihn im Header x-b10-code mit)
create or replace function public.b10_code_ok() returns boolean
language sql stable as $$
  select coalesce(current_setting('request.headers', true)::json ->> 'x-b10-code', '') = 'GRUPPEN-CODE'
$$;

drop policy if exists "b10 lesen"     on public.docs;
drop policy if exists "b10 anlegen"   on public.docs;
drop policy if exists "b10 aendern"   on public.docs;
drop policy if exists "b10 loeschen"  on public.docs;
create policy "b10 lesen"    on public.docs for select using (public.b10_code_ok());
create policy "b10 anlegen"  on public.docs for insert with check (public.b10_code_ok());
create policy "b10 aendern"  on public.docs for update using (public.b10_code_ok()) with check (public.b10_code_ok());
create policy "b10 loeschen" on public.docs for delete using (public.b10_code_ok());

grant select, insert, update, delete on public.docs to anon;

